def gate(changed, allowed, tests_ok, approved):
    reasons = []
    if not changed:
        reasons.append("empty")
    if set(changed) - set(allowed):
        reasons.append("scope")
    if tests_ok is not True:
        reasons.append("tests")
    if approved is not True:
        reasons.append("approval")
    return reasons
```

